const getWeekName = (weekNum, isDynamic, start, end) => {
  if (!isDynamic) {
    if (weekNum === 1) return "Week 1 (Apr 1 - Apr 7)";
    if (weekNum === 2) return "Week 2 (Apr 8 - Apr 14)";
    if (weekNum === 3) return "Week 3 (Apr 15 - Apr 21)";
    return "Week 4 (Apr 22 - Apr 30)";
  }
  const startDate = start ? new Date(start) : new Date("2026-05-10");
  const endDate = end ? new Date(end) : new Date("2026-05-27");
  const oneDayMs = 24 * 60 * 60 * 1000;
  
  const wStart = new Date(startDate.getTime() + (weekNum - 1) * 7 * oneDayMs);
  let wEnd = new Date(startDate.getTime() + (weekNum * 7 - 1) * oneDayMs);
  if (wEnd > endDate) {
    wEnd = endDate;
  }
  
  const formatShortDate = (d) => {
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  };
  return `Week ${weekNum} (${formatShortDate(wStart)} - ${formatShortDate(wEnd)})`;
};

const METRIC_DEFINITIONS = {
  spend: { title: "Ad Spend", desc: "Money spent on ads. Eg: You paid ₹100 to Flipkart for ads." },
  sales: { title: "Ad Sales", desc: "Sales from ad clicks. Eg: A customer clicked your ad & bought a ₹500 item." },
  roas: { title: "Ad ROAS", desc: "Return on Ad Spend. Eg: Spent ₹100, got ₹500 sales = 5x ROAS." },
  acos: { title: "ACOS", desc: "Ad Cost of Sales. Eg: Spent ₹100 for ₹500 sales = 20% ACOS." },
  ov_sales: { title: "Gross Sales", desc: "Total sales value of all orders placed before any cancellations. Eg: Customers placed orders worth ₹1000." },
  ov_orders: { title: "Gross Orders", desc: "Total orders placed before any cancellations." },
  sales_after_cancels: { title: "Sales After Cancels", desc: "Gross Sales minus Cancellations. Eg: ₹1000 Gross - ₹200 Cancels = ₹800." },
  net_sales: { title: "Net Sales", desc: "Final Sales after both Cancellations and Returns are deducted. Eg: ₹800 - ₹100 Returns = ₹700." },
  taos: { title: "TAOS", desc: "Total Ad Cost of Sales. Eg: Spent ₹100 on ads, total sales ₹1000 = 10% TAOS." },
  tcos: { title: "TCOS", desc: "Total Cost of Sales. Eg: All costs (product, ads, fees) take 80% of sales." },
  cancels: { title: "Cancellations", desc: "Cancelled orders. Eg: Customer cancelled before shipping." },
  returns: { title: "Returns", desc: "Returned orders. Eg: Customer returned item after delivery." },
  impressions: { title: "Impressions", desc: "Ad views. Eg: Your ad was shown 1000 times on Flipkart." },
  clicks: { title: "Clicks", desc: "Ad clicks. Eg: 50 people clicked your ad." }
};

const getWeekIndex = (dateStr, isDynamic, start, end) => {
  if (!dateStr) return 0;
  const d = new Date(dateStr.split('T')[0]);
  if (!isDynamic) {
    const day = d.getDate();
    if (day <= 7) return 0;
    if (day <= 14) return 1;
    if (day <= 21) return 2;
    return 3;
  }
  const startDate = start ? new Date(start) : new Date("2026-05-10");
  const endDate = end ? new Date(end) : new Date("2026-05-27");
  if (d < startDate) return 0;
  
  const totalMs = endDate - startDate;
  const oneDayMs = 24 * 60 * 60 * 1000;
  const totalDays = Math.ceil(totalMs / oneDayMs) + 1;
  const numWeeks = Math.max(1, Math.ceil(totalDays / 7));
  
  if (d > endDate) return numWeeks - 1;
  
  const diffMs = d.getTime() - startDate.getTime();
  const diffDays = Math.floor(diffMs / oneDayMs);
  const weekIdx = Math.floor(diffDays / 7);
  return Math.min(numWeeks - 1, Math.max(0, weekIdx));
};

const sanitizeStr = (s) => {
  if (typeof s !== 'string') return s;
  return s.replace(/lakshmi krishna naturals?/gi, '').replace(/lakshmi krishna/gi, '').trim();
};
const sanitizeData = (data) => {
  if (Array.isArray(data)) return data.map(sanitizeData);
  if (data && typeof data === 'object') {
    const out = {};
    for (let k in data) {
      if (k === 'keyword' || k === 'search_term') {
        out[k] = sanitizeStr(data[k]);
      } else {
        out[k] = sanitizeData(data[k]);
      }
    }
    // Normalize DB campaign performance keys to frontend expected keys
    if (out.impressions !== undefined && out.views === undefined) {
      out.views = Number(out.impressions || 0);
    }
    if (out.direct_units !== undefined && out.direct_units_sold === undefined) {
      out.direct_units_sold = Number(out.direct_units || 0);
    }
    if (out.indirect_units !== undefined && out.indirect_units_sold === undefined) {
      out.indirect_units_sold = Number(out.indirect_units || 0);
    }
    return out;
  }
  return data;
};

