  const handleDatePreset = (preset) => {
    const formatDate = (d) => {
      const offset = d.getTimezoneOffset() * 60000;
      const localISOTime = (new Date(d.getTime() - offset)).toISOString().slice(0, -1);
      return localISOTime.split('T')[0];
    };

    const getBaseDate = () => {
      if (isAmazonMode) {
        return new Date("2026-06-28");
      }
      const maxes = [
        dbDateBounds?.campaigns?.max,
        dbDateBounds?.pnl?.max,
        dbDateBounds?.sales?.max
      ].filter(Boolean);
      
      if (maxes.length > 0) {
        maxes.sort();
        const latestDbDate = maxes[maxes.length - 1];
        if (latestDbDate) {
          const d = new Date(latestDbDate);
          if (!isNaN(d.getTime())) return d;
        }
      }
      return new Date();
    };
    
    let start = getBaseDate();
    let end = getBaseDate();
    
    switch (preset) {
      case 'Today':
        break;
      case 'Yesterday':
        start.setDate(start.getDate() - 1);
        end.setDate(end.getDate() - 1);
        break;
      case 'This Week':
        const day = start.getDay();
        const diff = start.getDate() - day + (day === 0 ? -6 : 1);
        start.setDate(diff);
        break;
      case 'Last Week':
        start.setDate(start.getDate() - start.getDay() - 6);
        end.setDate(end.getDate() - end.getDay());
        break;
      case 'Last 7 Days':
        start.setDate(start.getDate() - 6);
        break;
      case 'Last 14 Days':
        start.setDate(start.getDate() - 13);
        break;
      case 'Last 30 Days':
        start.setDate(start.getDate() - 29);
        break;
      case 'Last 60 Days':
        start.setDate(start.getDate() - 59);
        break;
      default:
        break;
    }
    setDateFrom(formatDate(start));
    setDateTo(formatDate(end));
    setIsDatePickerOpen(false);
  };
  const [isDemoMode, setIsDemoMode] = useState(false);

